// Independent runner for identical saved original review signed inputs.
package main
import("bufio";"crypto/sha256";"encoding/hex";"encoding/json";"fmt";"os";"path/filepath";"mixer/services/protocol")
type Case struct{Name string `json:"name"`; Mode string `json:"mode"`; Input string `json:"input"`; InputSHA string `json:"inputSHA256"`; Payload string `json:"payload"`; Expected bool `json:"expected"`; Go bool `json:"go"`; Host protocol.Host `json:"host"`; Roots []protocol.Root `json:"roots"`; Now uint64 `json:"now"`}
func main(){out:=os.Args[1];file,e:=os.Open(filepath.Join(out,"cases.jsonl"));if e!=nil{panic(e)};defer file.Close();scanner:=bufio.NewScanner(file);scanner.Buffer(make([]byte,4096),2*1024*1024);rows:=[]map[string]any{}
for scanner.Scan(){var c Case;if e=json.Unmarshal(scanner.Bytes(),&c);e!=nil{panic(e)};if !c.Go{continue};if c.Mode!="signed"{panic("unexpected oracle mode")};raw,e:=os.ReadFile(filepath.Join(out,c.Input));if e!=nil{panic(e)};sum:=sha256.Sum256(raw);if hex.EncodeToString(sum[:])!=c.InputSHA{panic("input hash")};payload,e:=os.ReadFile(filepath.Join(out,c.Payload));if e!=nil{panic(e)};signed,e:=protocol.DecodeSignedManifestV3(raw);stage:="decode";if e==nil{stage="verify";e=protocol.VerifyManifestV3(signed,payload,c.Roots,c.Host,c.Now)};accepted:=e==nil;detail:="";if e!=nil{detail=e.Error()};rows=append(rows,map[string]any{"name":c.Name,"inputSHA256":c.InputSHA,"accepted":accepted,"expected":c.Expected,"stage":stage,"detail":detail});if accepted!=c.Expected{panic(fmt.Sprintf("oracle mismatch %s got %v expected %v: %s",c.Name,accepted,c.Expected,detail))}}
if e=scanner.Err();e!=nil{panic(e)};raw,e:=json.MarshalIndent(rows,"","  ");if e!=nil{panic(e)};if e=os.WriteFile(filepath.Join(out,"independent-go-results.json"),append(raw,'\n'),0600);e!=nil{panic(e)};fmt.Printf("independent identical-input signed cases: %d; all expected verdicts match\n",len(rows))}
